/**
 * Reduce a phone number to a comparable canonical form: a leading "+" (when the original
 * had one) followed by digits only.
 *
 * The masked input value produced by `v-maska` (e.g. "+1 212-555-0202") and the value the
 * backend stores and returns (e.g. "+12125550202") describe the same number, so comparing
 * them with this normalization applied prevents formatting-only differences from registering
 * as a change (e.g. in unsaved-changes dirty checks).
 */
export function normalizePhoneNumber(value: string | null | undefined): string {
  if (!value) return '';
  const trimmed = value.trim();
  const digits = trimmed.replace(/\D/g, '');
  return trimmed.startsWith('+') ? `+${digits}` : digits;
}
