import * as z from 'zod';
import { toTypedSchema } from '@vee-validate/zod';
import { phoneNumberRegex } from '../regularExpressions';

export const subcontractorCompanyFormSchemaObject = {
  name: z
    .string({ message: 'Company Name is required' })
    .trim()
    .nonempty({ message: 'Company Name is required' })
    .max(255, { message: 'Company Name must be at most 255 characters long' }),
  description: z
    .string({ message: 'Description is required' })
    .trim()
    .nonempty({ message: 'Description is required' })
    .max(10000, { message: 'Description must be at most 10000 characters long' }),
  logo_url: z.string({ message: 'Logo is required' }).trim().nonempty({ message: 'Logo is required' }),
  contact_information: z.object({
    contact_person: z
      .string({ message: 'Contact Person is required' })
      .trim()
      .nonempty({ message: 'Contact Person is required' })
      .max(255, { message: 'Contact Person must be at most 255 characters long' }),
    phone_number: z
      .string({ message: 'Phone Number is required' })
      .trim()
      .nonempty({ message: 'Phone Number is required' })
      .regex(phoneNumberRegex, { message: 'Enter a valid phone number in the format +1 ###-###-####' }),
    email: z
      .string({ message: 'Email is required' })
      .trim()
      .nonempty({ message: 'Email is required' })
      .email({ message: 'Enter a valid email address' })
      .max(255, { message: 'Email must be at most 255 characters long' }),
    legal_address: z
      .string({ message: 'Legal Address is required' })
      .trim()
      .nonempty({ message: 'Legal Address is required' })
      .max(500, { message: 'Legal Address must be at most 500 characters long' }),
  }),
};

export const subcontractorCompanyFormSchema = z.object(subcontractorCompanyFormSchemaObject);

export const formSchema = toTypedSchema(subcontractorCompanyFormSchema);

export type SubcontractorCompanyFormValues = z.infer<typeof subcontractorCompanyFormSchema>;
