<template>
  <form id="subcontractor-company-form" class="flex flex-col gap-6" @submit="onFormSubmit">
    <Card>
      <CardHeader>
        <CardTitle>General Information</CardTitle>
      </CardHeader>
      <CardContent>
        <div class="grid grid-cols-12 gap-6">
          <div class="col-span-12 lg:col-span-3">
            <FormItemWrapper label="Logo" name="logo_url">
              <template #default="{ slots }">
                <ImageCropUpload
                  circle
                  allow-svg
                  helper-text="Click to upload a logo (PNG or JPG)"
                  :preview-url="previewLogoUrl"
                  v-bind="slots.componentField"
                  @update:uploading="(value: boolean) => (isLogoUploading = value)"
                />
              </template>
            </FormItemWrapper>
          </div>

          <div class="col-span-12 lg:col-span-9 flex flex-col gap-4">
            <FormItemWrapper label="Company Name" name="name">
              <template #default="{ slots }">
                <Input id="name" type="text" placeholder="Company name" v-bind="slots.componentField" />
              </template>
            </FormItemWrapper>
            <FormItemWrapper label="Description" name="description">
              <template #default="{ slots }">
                <Textarea
                  id="description"
                  rows="8"
                  placeholder="Short description of the company, its focus areas, and operating regions."
                  class="resize-none"
                  v-bind="slots.componentField"
                />
              </template>
            </FormItemWrapper>
          </div>
        </div>
      </CardContent>
    </Card>

    <Card>
      <CardHeader>
        <CardTitle>Contact Information</CardTitle>
      </CardHeader>
      <CardContent>
        <div class="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div class="md:col-span-2">
            <FormItemWrapper label="Contact Person" name="contact_information.contact_person">
              <template #default="{ slots }">
                <Input
                  id="contact_information.contact_person"
                  type="text"
                  placeholder="First and last name"
                  v-bind="slots.componentField"
                />
              </template>
            </FormItemWrapper>
          </div>
          <FormItemWrapper label="Phone Number" name="contact_information.phone_number">
            <template #default="{ slots }">
              <Input
                id="contact_information.phone_number"
                v-maska
                type="tel"
                placeholder="+1 555-555-5555"
                data-maska="+# ###-###-####"
                v-bind="slots.componentField"
              />
            </template>
          </FormItemWrapper>
          <FormItemWrapper label="Email" name="contact_information.email">
            <template #default="{ slots }">
              <Input
                id="contact_information.email"
                type="text"
                placeholder="name@example.com"
                v-bind="slots.componentField"
              />
            </template>
          </FormItemWrapper>
          <div class="md:col-span-2">
            <FormItemWrapper label="Legal Address" name="contact_information.legal_address">
              <template #default="{ slots }">
                <Textarea
                  id="contact_information.legal_address"
                  rows="3"
                  placeholder="Street, city, state, zip"
                  class="resize-none"
                  v-bind="slots.componentField"
                />
              </template>
            </FormItemWrapper>
          </div>
        </div>
      </CardContent>
    </Card>

    <Card>
      <CardContent class="flex justify-end gap-2">
        <NuxtLink v-if="cancelTo" :to="cancelTo">
          <Button variant="outline" type="button">Cancel</Button>
        </NuxtLink>
        <Button type="submit" :loading="isSubmitting" :disabled="isSubmitDisabled">{{ submitLabel }}</Button>
      </CardContent>
    </Card>

    <NavigationGuard
      v-if="guardUnsavedChanges"
      :saved-data="initialValues"
      :changed-data="currentValues"
      title="Warning"
      description="You have unsaved changes. Save them before leaving this page."
      confirm-text="Discard Changes"
    />
  </form>
</template>

<script lang="ts" setup>
import { useForm } from 'vee-validate';
import { cloneDeep, isEqual } from 'lodash';
import type { TypedNuxtLink } from '#build/typed-router/typed-router';
import {
  formSchema,
  type SubcontractorCompanyFormValues,
} from '~/constants/validationSchemas/subcontractorCompanyForm';

interface Props {
  initialValues?: Partial<SubcontractorCompanyFormValues>;
  previewLogoUrl?: string;
  isSaving?: boolean;
  submitLabel: string;
  cancelTo?: TypedNuxtLink['to'] | null;
  guardUnsavedChanges?: boolean;
  disableSubmitWhenPristine?: boolean;
  onSubmit: (values: SubcontractorCompanyFormValues) => Promise<void>;
}

const props = withDefaults(defineProps<Props>(), {
  initialValues: undefined,
  previewLogoUrl: undefined,
  isSaving: false,
  cancelTo: null,
  guardUnsavedChanges: false,
  disableSubmitWhenPristine: false,
});

const isLogoUploading = ref(false);
const isSubmitting = computed(() => props.isSaving);

const { handleSubmit, values } = useForm({
  validationSchema: formSchema,
  initialValues: props.initialValues,
});

// Snapshot the form values before comparing: vee-validate exposes `values` as a reactive
// Proxy that lodash isEqual does not compare reliably against a plain object. While
// snapshotting, normalize the phone number so a formatting-only difference does not count
// as a change — the masked input value (e.g. "+1 212-555-0202") and the value the backend
// stores and returns (e.g. "+12125550202") are the same number.
const currentValues = computed(() => {
  const snapshot = cloneDeep(values);
  if (snapshot.contact_information?.phone_number != null) {
    snapshot.contact_information.phone_number = normalizePhoneNumber(snapshot.contact_information.phone_number);
  }
  return snapshot;
});

// Drive both the NavigationGuard and the disabled Save button from the SAME comparison
// so they always agree on "no changes".
const isUnchanged = computed(() => isEqual(props.initialValues, currentValues.value));
const isSubmitDisabled = computed(
  () => (props.disableSubmitWhenPristine && isUnchanged.value) || isLogoUploading.value
);

const onFormSubmit = handleSubmit(async (formValues) => {
  try {
    await props.onSubmit(formValues);
  } catch {
    // Error toast is surfaced by the mutation's onError; keep form state so the user can retry.
  }
});
</script>
